#!/usr/bin/env python3
from __future__ import annotations
import base64,zlib
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
FILES={'scripts/generate_rma073_synthetic_data.py': '', 'scripts/fit_calibration_profile.py': '', 'scripts/verify_calibration_profile.py': '', 'scripts/tests/test_calibration_fitting.py': ''}
for relative,payload in FILES.items():
 path=ROOT/relative
 path.parent.mkdir(parents=True,exist_ok=True)
 path.write_bytes(zlib.decompress(base64.b64decode(payload)))
print(f"wrote {len(FILES)} files")
